package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures of a sheet consolidated over it and all its descendants (the sheets naming it as their
 * parent, theirs, and so on), each sheet's as that sheet shows them now.
 */
@Service
public class Consolidation {

    /** The number of people, and the due-totals and overdue-totals added up. */
    public record Consolidated(int peopleCount, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    private final SheetRepository sheets;
    private final Rollups rollups;

    public Consolidation(SheetRepository sheets, Rollups rollups) {
        this.sheets = sheets;
        this.rollups = rollups;
    }

    /** The sheet's figures added to those of all its descendants. */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId) {
        List<String> all = new ArrayList<>();
        all.add(sheetId);
        all.addAll(sheets.descendants(sheetId));
        int people = 0;
        BigDecimal due = BigDecimal.ZERO.setScale(2);
        BigDecimal overdue = BigDecimal.ZERO.setScale(2);
        for (String id : all) {
            Rollups.Rollup rollup = rollups.take(id);
            people += rollup.people().size();
            due = due.add(rollup.dueTotal());
            overdue = overdue.add(rollup.overdueTotal());
        }
        return new Consolidated(people, due, overdue);
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class ConsolidationController {

    /** What the screen is told about the consolidated figures: the due amounts with two decimals. */
    public record ConsolidatedView(int peopleCount, String dueTotal, String overdueTotal) {
    }

    private final Consolidation consolidation;

    public ConsolidationController(Consolidation consolidation) {
        this.consolidation = consolidation;
    }

    /** The sheet's figures over it and all its descendants, as each stands now (an as-of date does not apply). */
    @GetMapping("/{id}/consolidated")
    public ConsolidatedView consolidated(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id) {
        Consolidation.Consolidated figures = consolidation.of(id);
        return new ConsolidatedView(figures.peopleCount(), figures.dueTotal().toPlainString(),
                figures.overdueTotal().toPlainString());
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/**
 * A sheet's figures over it and all its descendants (the sheets naming it as their parent, theirs, and
 * so on), each sheet's as that sheet shows them now.
 */
export interface ConsolidatedView {
  peopleCount: number;
  /** The sheets' due-totals added up, with two decimals. */
  dueTotal: string;
  /** The sheets' overdue-totals added up, with two decimals. */
  overdueTotal: string;
}

// The consolidated figures, read from the store.
@Injectable({ providedIn: 'root' })
export class ConsolidatedApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<ConsolidatedView> {
    return firstValueFrom(this.http.get<ConsolidatedView>(`/api/sheets/${encodeURIComponent(sheet)}/consolidated`));
  }
}
import { Component, effect, inject, input, signal, untracked } from '@angular/core';
import { ConsolidatedApi, ConsolidatedView } from '../../core/consolidated';
import { Session } from '../../core/session';

// The sheet's figures consolidated over it and all its descendants: the number of people, and each
// sheet's due-total and overdue-total, as that sheet shows them, added up. Re-read on every sheet load
// and whenever the sheet's own figures move.
@Component({
  selector: 'app-consolidated',
  template: `
    <section aria-label="Consolidated figures">
      <p>Consolidated people <strong data-testid="consolidated-people-count">{{ figures()?.peopleCount }}</strong></p>
      <p>Consolidated due <strong data-testid="consolidated-due-total">{{ figures()?.dueTotal }}</strong></p>
      <p>Consolidated overdue <strong data-testid="consolidated-overdue-total">{{ figures()?.overdueTotal }}</strong></p>
    </section>
  `,
})
export class Consolidated {
  private readonly session = inject(Session);
  private readonly api = inject(ConsolidatedApi);

  /** The sheet's own figures as shown: a move in any of them re-reads the consolidated ones. */
  readonly peopleCount = input.required<number>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();

  protected readonly figures = signal<ConsolidatedView | null>(null);
  /** Counts reads, so only the answer to the latest one is shown. */
  private reads = 0;

  constructor() {
    // Every sheet load clears the figures shown and re-reads them.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.figures.set(null);
        if (sheet) void this.reload(sheet);
      });
    });
    // A move in the sheet's own today or figures re-reads them.
    effect(() => {
      this.session.today();
      this.peopleCount();
      this.dueTotal();
      this.overdueTotal();
      untracked(() => {
        const sheet = this.session.sheet();
        if (sheet) void this.reload(sheet);
      });
    });
  }

  private async reload(sheet: string): Promise<void> {
    const read = ++this.reads;
    try {
      const figures = await this.api.get(sheet);
      if (read === this.reads && this.session.sheet() === sheet) this.figures.set(figures);
    } catch {
      // Left as it was: the next load or change reads them again.
    }
  }
}

