    public String getAlias() {
        return alias;
    }

    public String getAliasKey() {
        return aliasKey;
    }

    @Override
    public boolean equals(Object other) {
        return other instanceof Alias that && alias.equals(that.alias);
    }

    @Override
    public int hashCode() {
        return alias.hashCode();
    }
}

